import{_ as t,o as n,c as a,a6 as o}from"./chunks/framework.BrkgobfX.js";const u=JSON.parse('{"title":"表示字段","description":"Content-Type、Content-Encoding、Content-Language、Content-Location——描述消息体的四个字段。","frontmatter":{"title":"表示字段","description":"Content-Type、Content-Encoding、Content-Language、Content-Location——描述消息体的四个字段。","source":"https://daiw.org/manual/http11/representation-fields"},"headers":[],"relativePath":"manual/computer-programming/http11/representation-fields.md","filePath":"manual/computer-programming/http11/representation-fields.md"}'),s={name:"manual/computer-programming/http11/representation-fields.md"};function d(i,e,c,r,p,l){return n(),a("div",null,[...e[0]||(e[0]=[o(`<h1 id="表示字段" tabindex="-1">表示字段 <a class="header-anchor" href="#表示字段" aria-label="Permalink to &quot;表示字段&quot;">​</a></h1><p><strong>表示（representation）</strong> = 元数据 + 数据。表示字段描述的是「体里装的是什么」，与「资源是什么」分开——同一资源可有多个表示（不同语言、不同编码）。</p><h2 id="content-type" tabindex="-1">Content-Type <a class="header-anchor" href="#content-type" aria-label="Permalink to &quot;Content-Type&quot;">​</a></h2><div class="language-text vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Content-Type = media-type</span></span>
<span class="line"><span>media-type   = type &quot;/&quot; subtype parameters</span></span>
<span class="line"><span>type         = token</span></span>
<span class="line"><span>subtype      = token</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br></div></div><p>指明体的<strong>媒体类型</strong>。缺失时接收方 <strong>MAY</strong> 自行嗅探或按 <code>application/octet-stream</code> 处理。</p><ul><li><code>type</code> 与 <code>subtype</code> <strong>大小写不敏感</strong>，惯例小写。</li><li>参数名大小写不敏感；参数值是否敏感由具体类型定义。</li><li><code>+</code> 后缀表示结构化语法：<code>application/json-patch+json</code> 按 JSON 解析。</li></ul><h3 id="charset-参数" tabindex="-1">charset 参数 <a class="header-anchor" href="#charset-参数" aria-label="Permalink to &quot;charset 参数&quot;">​</a></h3><div class="language-text vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Content-Type: text/html; charset=UTF-8</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br></div></div><ul><li>值<strong>大小写不敏感</strong>，取自 IANA 字符集注册表。</li><li>对 <code>text/*</code> 尤为关键：缺失时各实现的默认值不一致（历史默认 ISO-8859-1，现代浏览器多按 UTF-8 或嗅探），是乱码的首要成因。</li><li><code>application/json</code> <strong>不接受</strong> <code>charset</code> 参数——RFC 8259 规定 JSON 必须是 UTF-8，写 <code>charset=UTF-8</code> 无效但无害。</li></ul><h3 id="boundary-参数" tabindex="-1">boundary 参数 <a class="header-anchor" href="#boundary-参数" aria-label="Permalink to &quot;boundary 参数&quot;">​</a></h3><p><code>multipart/*</code> 必需，且<strong>大小写敏感</strong>：</p><div class="language-text vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Content-Type: multipart/form-data; boundary=----WebKitFormBoundaryXYZ</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br></div></div><ul><li>长度 1–70 字符，不得以空白结尾。</li><li>体中每个分隔行是 <code>--</code> + boundary，结束行是 <code>--</code> + boundary + <code>--</code>。</li><li>值含特殊字符时须用 <code>quoted-string</code>。</li></ul><h3 id="嗅探与防护" tabindex="-1">嗅探与防护 <a class="header-anchor" href="#嗅探与防护" aria-label="Permalink to &quot;嗅探与防护&quot;">​</a></h3><p>服务端应始终发送准确的 <code>Content-Type</code>。浏览器的 MIME 嗅探会把 <code>text/plain</code> 的内容当 HTML 执行，造成 XSS——用响应字段 <code>X-Content-Type-Options: nosniff</code> 关闭嗅探（非 HTTP 核心规范，但属必备实践）。</p><h2 id="content-encoding" tabindex="-1">Content-Encoding <a class="header-anchor" href="#content-encoding" aria-label="Permalink to &quot;Content-Encoding&quot;">​</a></h2><div class="language-text vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Content-Encoding = #content-coding</span></span>
<span class="line"><span>content-coding   = token</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br></div></div><p>指明体已被施加的<strong>内容编码</strong>，接收方需逆序解码才能得到原始表示。</p><table tabindex="0"><thead><tr><th>值</th><th>说明</th></tr></thead><tbody><tr><td><code>gzip</code></td><td>RFC 1952，LZ77 + CRC32。别名 <code>x-gzip</code></td></tr><tr><td><code>deflate</code></td><td>RFC 1950 zlib 格式。历史实现混淆（有的发裸 deflate），兼容性差</td></tr><tr><td><code>br</code></td><td>Brotli，RFC 7932。文本压缩率优于 gzip</td></tr><tr><td><code>zstd</code></td><td>Zstandard，RFC 8878</td></tr><tr><td><code>compress</code></td><td>LZW，已废弃。别名 <code>x-compress</code></td></tr><tr><td><code>identity</code></td><td>不编码。<strong>仅可用于 <code>Accept-Encoding</code></strong>，不得出现在 <code>Content-Encoding</code></td></tr></tbody></table><p>关键性质：</p><ul><li><strong>端到端</strong>——代理<strong>不得</strong>擅自改动（与逐跳的 <code>Transfer-Encoding</code> 相反）。</li><li>编码是<strong>表示的一部分</strong>：<code>ETag</code> 针对编码后的字节，gzip 版与非 gzip 版必须有<strong>不同的 ETag</strong>，且响应须带 <code>Vary: Accept-Encoding</code>。</li><li>多个编码按<strong>应用顺序</strong>列出：<code>Content-Encoding: gzip, br</code> 表示先 gzip 再 br（罕见）。</li><li><code>Content-Length</code> 计的是<strong>编码后</strong>的长度。</li><li>客户端不支持所收编码时无法恢复；请求体编码不被支持则服务端返回 <code>415</code> + <code>Accept-Encoding</code>。</li></ul><h2 id="content-language" tabindex="-1">Content-Language <a class="header-anchor" href="#content-language" aria-label="Permalink to &quot;Content-Language&quot;">​</a></h2><div class="language-text vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Content-Language = #language-tag</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br></div></div><p>标注表示的<strong>目标受众语言</strong>（RFC 5646 语言标签，大小写不敏感）：</p><div class="language-text vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Content-Language: zh-CN</span></span>
<span class="line"><span>Content-Language: en, de</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br></div></div><ul><li>多值表示内容<strong>同时面向</strong>多种语言受众，<strong>不是</strong>「内含多语言片段」。</li><li>描述的是受众而非文字：一份写给中文读者的英文教材可标 <code>zh-CN</code>。</li><li>与 <code>Accept-Language</code> 配对做协商，需配 <code>Vary: Accept-Language</code>。</li></ul><h2 id="content-location" tabindex="-1">Content-Location <a class="header-anchor" href="#content-location" aria-label="Permalink to &quot;Content-Location&quot;">​</a></h2><div class="language-text vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Content-Location = absolute-URI / partial-URI</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br></div></div><p>给出<strong>该特定表示</strong>的直接 URI。相对引用以请求目标 URI 为基准解析。</p><p>与 <code>Location</code> 的区别（高频混淆）：</p><table tabindex="0"><thead><tr><th></th><th><code>Content-Location</code></th><th><code>Location</code></th></tr></thead><tbody><tr><td>指向</td><td>本响应体所对应表示的 URI</td><td>重定向目标 / 新建资源</td></tr><tr><td>出现于</td><td>任何带体的响应</td><td><code>3xx</code>、<code>201</code></td></tr><tr><td>客户端动作</td><td>无，仅元信息</td><td>跳转 / 记录新资源</td></tr></tbody></table><p>典型用途：<code>/article</code> 内容协商后返回中文版，带 <code>Content-Location: /article.zh.html</code> 告知该版本的固定地址。</p><p><strong>注意</strong>：<code>Content-Location</code> <strong>不改变</strong>请求的目标 URI，也<strong>不改变</strong>缓存键——缓存仍以请求 URI 存储。</p><h2 id="表示字段在请求中的含义" tabindex="-1">表示字段在请求中的含义 <a class="header-anchor" href="#表示字段在请求中的含义" aria-label="Permalink to &quot;表示字段在请求中的含义&quot;">​</a></h2><p>这些字段出现在<strong>请求</strong>里时，描述的是请求体：</p><div class="language-text vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>POST /upload HTTP/1.1</span></span>
<span class="line"><span>Content-Type: image/png</span></span>
<span class="line"><span>Content-Encoding: gzip</span></span>
<span class="line"><span>Content-Length: 20480</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br></div></div><p>服务端处理规则：</p><ul><li>不支持的 <code>Content-Type</code> → <code>415</code>，<strong>SHOULD</strong> 带 <code>Accept</code>。</li><li>不支持的 <code>Content-Encoding</code> → <code>415</code>，<strong>SHOULD</strong> 带 <code>Accept-Encoding</code>。</li><li><code>GET</code>/<code>DELETE</code> 带这些字段时语义未定义，不应发送。</li></ul><p>下一篇：<a href="/Front2Full/manual/computer-programming/http11/content-negotiation">内容协商</a>——Accept 系列字段与 q 值排序规则。</p>`,39)])])}const h=t(s,[["render",d]]);export{u as __pageData,h as default};
